CREATE DATABASE IF NOT EXISTS job_tracker CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE job_tracker;
CREATE TABLE IF NOT EXISTS companies (company_id INT AUTO_INCREMENT PRIMARY KEY, company_name VARCHAR(100) NOT NULL, industry VARCHAR(50), website VARCHAR(200), city VARCHAR(50), state VARCHAR(50), notes TEXT);
CREATE TABLE IF NOT EXISTS jobs (job_id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, job_title VARCHAR(100) NOT NULL, job_type ENUM('Full-time','Part-time','Contract','Internship'), salary_min INT, salary_max INT, job_url VARCHAR(300), date_posted DATE, requirements JSON, CONSTRAINT fk_jobs_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE RESTRICT, INDEX idx_jobs_company (company_id), INDEX idx_jobs_salary (salary_min));
CREATE TABLE IF NOT EXISTS applications (application_id INT AUTO_INCREMENT PRIMARY KEY, job_id INT NOT NULL, application_date DATE NOT NULL, status ENUM('Applied','Screening','Interview','Offer','Rejected','Withdrawn') NOT NULL DEFAULT 'Applied', resume_version VARCHAR(50), cover_letter_sent BOOLEAN DEFAULT FALSE, interview_data JSON, CONSTRAINT fk_app_job FOREIGN KEY (job_id) REFERENCES jobs(job_id) ON DELETE RESTRICT, INDEX idx_app_status (status), INDEX idx_app_date (application_date));
CREATE TABLE IF NOT EXISTS contacts (contact_id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, contact_name VARCHAR(100) NOT NULL, title VARCHAR(100), email VARCHAR(100), phone VARCHAR(20), linkedin_url VARCHAR(200), notes TEXT, CONSTRAINT fk_contact_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE RESTRICT, INDEX idx_contacts_company (company_id));
